sql:
SELECT posto_id FROM postos WHERE cnpj IN (
    SELECT DISTINCT cnpj FROM coletas WHERE produto = 'DIESEL S10' AND data_coleta BETWEEN '2025-09-01' AND '2026-09-30'
)

first_sql:
SELECT regiao FROM municipios WHERE nome = 'SÃO PAULO' AND uf = 'SP' AND capital = TRUE AND municipio_id IN (
    SELECT posto_id FROM postos WHERE cnpj IN (
        SELECT posto_id FROM coletas WHERE produto = 'DIESEL S10' AND data_coleta BETWEEN '2025-09-01' AND '2026-09-30'
    )
) GROUP BY regiao ORDER BY AVG(valor_venda) DESC LIMIT 1

