SELECT DISTINCT uf, AVG(valor_venda) AS media FROM coletas WHERE produto = 'GASOLINA' AND data_coleta >= date_trunc('month', '2026-09-01') GROUP BY uf HAVING AVG(valor_venda) > (SELECT AVG(valor_venda) FROM coletas WHERE produto = 'GASOLINA' AND data_coleta >= date_trunc('month', '2026-09-01') AND municipio_id IN (SELECT municipio_id FROM municipios WHERE capital = TRUE)) ORDER BY media DESC LIMIT 1;
